// setQosParameters parses the QoS related parameters from the StorageClass
// and, when provided, calculates the QoS limits based on the volume capacity.
func (rbdVol *rbdVolume) setQosParameters(ctx context.Context, params map[string]string) error {
	baseQosVolSize := ""
	if v, ok := params[baseVolSizeBytes]; ok && v != "" {
		baseQosVolSize = v
	}
	rbdQosParameters := parseQosParams(params)
	for _, param := range rbdQosParameters {
		if param.provide {
			err := calcQosBasedOnCapacity(ctx, rbdVol, *param, baseQosVolSize)
			if err != nil {
				return err
			}
		}
	}

	return nil
}

